<section class="page-header"><div><a class="back-link" href="<?= url('invoices') ?>"><i class="fa-solid fa-arrow-left"></i> Back to invoices</a><h1><?= e($invoice['invoice_number']) ?></h1><p><?= e($invoice['company_name']) ?> · Due <?= e(date('d M Y',strtotime($invoice['due_date']))) ?></p></div><div class="page-actions"><a class="button button-secondary" target="_blank" href="<?= url('invoices/'.$invoice['id'].'/print') ?>"><i class="fa-solid fa-print"></i> Print</a><a class="button button-primary" href="<?= url('invoices/'.$invoice['id'].'/print?format=pdf') ?>"><i class="fa-solid fa-file-pdf"></i> Download PDF</a></div></section>
<div class="invoice-view-grid"><section class="panel invoice-document"><div class="invoice-doc-head"><div><span class="brand-mark">RM</span><div><strong>Rankers Mind</strong><small>Kolkata, West Bengal, India</small></div></div><div><span class="status-badge <?= status_class($invoice['status']) ?>"><?= e($invoice['status']) ?></span><h2><?= e($invoice['invoice_type']) ?></h2></div></div><div class="invoice-meta"><div><span>Bill to</span><strong><?= e($invoice['company_name']) ?></strong><p><?= nl2br(e($invoice['billing_address']?:$invoice['city'].', '.$invoice['state'])) ?></p><small><?= e($invoice['gstin']?'GSTIN '.$invoice['gstin']:'') ?></small></div><dl><div><dt>Invoice no.</dt><dd><?= e($invoice['invoice_number']) ?></dd></div><div><dt>Invoice date</dt><dd><?= e(date('d M Y',strtotime($invoice['invoice_date']))) ?></dd></div><div><dt>Due date</dt><dd><?= e(date('d M Y',strtotime($invoice['due_date']))) ?></dd></div><div><dt>Project</dt><dd><?= e($invoice['project_name']?:'General') ?></dd></div></dl></div><div class="table-scroll"><table class="data-table invoice-lines"><thead><tr><th>Description</th><th>Qty</th><th>Rate</th><th>Tax</th><th>Amount</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><strong><?= e($item['description']) ?></strong><small class="cell-sub"><?= e($item['hsn_sac']?'HSN/SAC '.$item['hsn_sac']:'') ?></small></td><td><?= e($item['quantity']) ?></td><td><?= money($item['rate']) ?></td><td><?= e($item['tax_percent']) ?>%<small class="cell-sub"><?= money($item['tax_amount']) ?></small></td><td><strong><?= money($item['amount']) ?></strong></td></tr><?php endforeach;?></tbody></table></div><div class="invoice-totals"><dl><div><dt>Subtotal</dt><dd><?= money($invoice['subtotal']) ?></dd></div><div><dt>Tax</dt><dd><?= money($invoice['tax_total']) ?></dd></div><div><dt>Additional charges</dt><dd><?= money($invoice['additional_charges']) ?></dd></div><div class="summary-total"><dt>Total</dt><dd><?= money($invoice['grand_total']) ?></dd></div><div><dt>Paid</dt><dd class="text-success"><?= money($invoice['paid_amount']) ?></dd></div><div><dt>Pending</dt><dd class="text-danger"><?= money($invoice['pending_amount']) ?></dd></div></dl></div><?php if($invoice['notes']):?><div class="invoice-note"><strong>Notes</strong><p><?= nl2br(e($invoice['notes'])) ?></p></div><?php endif;?></section>
<aside><section class="panel"><div class="panel-head"><div><h2>Payment history</h2><p>Partial and full receipts</p></div></div><div class="compact-list"><?php foreach($payments as $payment):?><div class="list-row"><span class="list-icon"><i class="fa-solid fa-indian-rupee-sign"></i></span><span class="list-main"><strong><?= money($payment['amount']) ?></strong><small><?= e($payment['payment_number']) ?> · <?= e($payment['payment_mode']) ?></small></span><span class="list-date"><?= e(date('d M',strtotime($payment['payment_date']))) ?></span><a class="icon-button" href="<?= url('payments/'.$payment['id'].'/receipt?format=pdf') ?>" title="Download receipt"><i class="fa-solid fa-receipt"></i></a></div><?php endforeach;?><?php if(!$payments):?><div class="empty-inline">No payments recorded.</div><?php endif;?></div></section><?php if(can('payments.create')&&(float)$invoice['pending_amount']>0):?><section class="panel payment-panel"><div class="panel-head"><div><h2>Record payment</h2><p>Maximum <?= money($invoice['pending_amount']) ?></p></div></div><form class="mini-form" method="post" action="<?= url('invoices/'.$invoice['id'].'/payments') ?>"><?= csrf_field() ?><label>Amount<input type="number" name="amount" value="<?= e($invoice['pending_amount']) ?>" min="0.01" max="<?= e($invoice['pending_amount']) ?>" step="0.01" required></label><label>Date<input type="date" name="payment_date" value="<?= date('Y-m-d') ?>" required></label><label>Payment mode<select name="payment_mode"><option>Bank Transfer</option><option>UPI</option><option>Cash</option><option>Cheque</option><option>Card</option><option>Other</option></select></label><label>Reference number<input name="reference_number"></label><label>Bank / account<input name="bank_account"></label><label>Notes<textarea name="notes"></textarea></label><button class="button button-success button-block">Record payment</button></form></section><?php endif;?></aside></div>
